from pathlib import Path
import base64,hashlib,json,sys
from playwright.sync_api import sync_playwright
root=Path(__file__).resolve().parents[2];module=root/'examples/editor-home/ui/blueprint-viewport.js';source=module.read_bytes();url='data:text/javascript;base64,'+base64.b64encode(source).decode()
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-gpu']);page=browser.new_page()
 page.set_content('''<style>.bp-scroll{position:relative;width:700px;height:400px;overflow:hidden}.bp-canvas{position:relative;transform-origin:0 0}.bp-node{position:absolute;width:250px;height:180px}</style><section id="host"><input data-bp-zoom><button data-bp-percent></button><button data-bp-fit></button><div class="bp-scroll"><div class="bp-canvas"><svg class="bp-wires"></svg><article class="bp-node" data-bp-node="source"><header data-bp-drag="source"><button data-bp-exec-in="source">in</button><button data-bp-exec-out="source" data-exec-port="next">out</button></header></article><article class="bp-node" data-bp-node="target"><header data-bp-drag="target"><button data-bp-exec-in="target">in</button><button data-bp-exec-out="target" data-exec-port="next">out</button></header></article></div></div></section>''')
 results=page.evaluate('''async url=>{const module=await import(url),host=document.querySelector('#host'),$=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)];const results=[];for(const port of ['next','missing','bad"]port']){const data={id:'owned-graph',nodes:[{id:'source',control:'next'},{id:'target',control:'next'}],edges:[{from:'source',port,to:'target'}]},w={body:host,el:host,meta:{}};try{const view=module.mountBlueprintViewport({w,data,$,$$,persist(){},isCurrent:()=>true,hasWire:()=>false,cancelWire(){}});results.push({port,opened:true,paths:host.querySelectorAll('.bp-wires path').length});view.dispose();}catch(error){results.push({port,opened:false,error:error.name+': '+error.message});}}return results;}''',url)
 browser.close()
result={'kind':'owned-DOM-component-probe-not-full-editor','sourceSha256':hashlib.sha256(source).hexdigest(),'cases':results,'allOpened':all(row['opened'] for row in results),'expectedPaths':[1,0,0]};Path(sys.argv[1]).write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
if '--require-pass' in sys.argv:assert result['allOpened'] and [row['paths'] for row in results]==result['expectedPaths']
